{"source":"#include<stdio.h>
#include<string.h>
int main(int argc, char *argv[])
{
    int a, i, len, len2, j, ctr, l, ct=0;
    char gogl[100001];
    char apple[31];
    scanf("%s", gogl);
    scanf("%s", apple);
    len=strlen(gogl);
    len2=strlen(apple);
    for(i=0; i<=len-len2; i++)
    {
        ctr=1;
        for(j=0; j<len2; j++)
        {
            if(gogl[i+j]!=apple[j])
            {
                ctr=0;
                break;
            }
        }
        if(ctr!=0)
        {
            ct++;
        }
    }
    printf("%d", ct);
    return 0;
}"}
